import json, pathlib
customers = {c['id']: c for c in json.loads(pathlib.Path('/tmp/customers.json').read_text())}
orders = json.loads(pathlib.Path('/tmp/orders.json').read_text())
totals = {}
for o in orders:
    region = customers[o['customer_id']]['region']
    totals[region] = totals.get(region, 0) + o['amount']
pathlib.Path('/tmp/totals.json').write_text(json.dumps(totals))
print(totals)
